// Parse JSON response from RAG pipeline
const output = $input.first().json.stdout;

try {
  // Try to parse as JSON
  const result = JSON.parse(output);

  // Format response for chat
  let chatOutput = result.answer || "I couldn't generate an answer.";

  // Add sources if available
  if (result.sources && result.sources.length > 0) {
    const sourceNames = result.sources.map(s => {
      // Extract filename from path
      const parts = s.split('/');
      return parts[parts.length - 1] || s;
    }).join(', ');
    chatOutput += `\n\n📚 Sources: ${sourceNames}`;
  }

  // Handle errors
  if (result.error) {
    chatOutput = `⚠️ Error: ${result.error}`;
  }

  return {
    json: {
      chatOutput: chatOutput,
      answer: result.answer,
      sources: result.sources || [],
      confidence: result.confidence || 0,
      error: result.error || null
    }
  };
} catch (e) {
  // If JSON parsing fails, try to extract meaningful error
  const errorMsg = output.includes('Error') ? output : `Failed to parse response: ${e.message}`;
  return {
    json: {
      chatOutput: `⚠️ Error: ${errorMsg}`,
      answer: null,
      sources: [],
      confidence: 0,
      error: errorMsg
    }
  };
}
